/**
 * @suppress
 */
public object FfiConverterTypeAipassCore: FfiConverter<AipassCore, Long> {
    override fun lower(value: AipassCore): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): AipassCore {
        return AipassCore(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): AipassCore {
        return lift(buf.getLong())
    }

