/**
 * @suppress
 */
public object FfiConverterTypeSecretStore: FfiConverter<SecretStore, Long> {
    internal val handleMap = UniffiHandleMap<SecretStore>()

    override fun lower(value: SecretStore): Long {
        if (value is SecretStoreImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): SecretStore {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return SecretStoreImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): SecretStore {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: SecretStore) = 8UL

    override fun write(value: SecretStore, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



