/**
 * Error returned by every fallible core method.
 */
sealed class CoreException: kotlin.Exception() {
    
    /**
     * `code` is a stable machine code (e.g. `LOCKED`, `NOT_FOUND`, `SYNC_CONFLICT`);
     * `message` is a user-presentable explanation in the current locale.
     */
    class Failure(
        
        val `code`: kotlin.String, 
        
        val `message`: kotlin.String
        ) : CoreException() {
        override val message
            get() = "code=${ `code` }, message=${ `message` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<CoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): CoreException = FfiConverterTypeCoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeCoreError : FfiConverterRustBuffer<CoreException> {
    override fun read(buf: ByteBuffer): CoreException {
        

        return when(buf.getInt()) {
            1 -> CoreException.Failure(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CoreException): ULong {
        return when(value) {
            is CoreException.Failure -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: CoreException, buf: ByteBuffer) {
        when(value) {
            is CoreException.Failure -> {
                buf.putInt(1)
                FfiConverterString.write(value.`code`, buf)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





/**
 * Error a native [`crate::SecretStore`] implementation reports.
 */
sealed class SecretStoreException: kotlin.Exception() {
    
    /**
     * The user cancelled or failed biometric / passcode authentication.
     */
    class UserCancelled(
        ) : SecretStoreException() {
        override val message
            get() = ""
    }
    
    /**
     * Keychain / Keystore unavailable (device locked, item inaccessible, …).
     */
    class Unavailable(
        
        val `reason`: kotlin.String
        ) : SecretStoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * An unexpected error inside the native callback.
     */
    class Unexpected(
        
        val `reason`: kotlin.String
        ) : SecretStoreException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SecretStoreException> {
        override fun lift(error_buf: RustBuffer.ByValue): SecretStoreException = FfiConverterTypeSecretStoreError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSecretStoreError : FfiConverterRustBuffer<SecretStoreException> {
    override fun read(buf: ByteBuffer): SecretStoreException {
        

        return when(buf.getInt()) {
            1 -> SecretStoreException.UserCancelled()
            2 -> SecretStoreException.Unavailable(
                FfiConverterString.read(buf),
                )
            3 -> SecretStoreException.Unexpected(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SecretStoreException): ULong {
        return when(value) {
            is SecretStoreException.UserCancelled -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SecretStoreException.Unavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SecretStoreException.Unexpected -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SecretStoreException, buf: ByteBuffer) {
        when(value) {
            is SecretStoreException.UserCancelled -> {
                buf.putInt(1)
                Unit
            }
            is SecretStoreException.Unavailable -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SecretStoreException.Unexpected -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




